import { chromium } from '@playwright/test';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
page.on('console', msg => console.log('console', msg.type(), msg.text()));
page.on('pageerror', err => console.log('pageerror', err.message));
await page.goto('http://127.0.0.1:3010/');
console.log('title', await page.title());
console.log('brand visible', await page.locator('.app-shell > .sidebar').getByText('POWERPROMPT').isVisible());
await page.getByRole('button', { name: /Reveal search/ }).click();
console.log('search open', await page.locator('.searchbar.open').count());
await page.getByPlaceholder(/Search prompts/).fill('cold email');
console.log('open button visible', await page.getByRole('button', { name: 'Open The Cold-Email Closer' }).isVisible());
await page.getByRole('button', { name: 'Open The Cold-Email Closer' }).click({ force: true });
console.log('dialog count after force', await page.getByRole('dialog').count());
console.log('body classes', await page.locator('body').evaluate(el => el.innerHTML.includes('lb open')));
await browser.close();
